/**
 * Metadata for the site.
 */
export interface SiteMeta {
  /** The site title. */
  title: string;
  /** A short description of the site. */
  description: string;
  /** Optional locale identifier such as "en" or "en-US". */
  locale?: string;
}

/**
 * A call-to-action shown in the hero section.
 */
export interface HeroAction {
  /** Visible label for the action. */
  label: string;
  /** Destination URL or path. */
  href: string;
  /** Visual emphasis for the action button. */
  variant: 'primary' | 'secondary';
}

/**
 * Color tone configuration for hero visual elements.
 */
export interface HeroVisualTone {
  /** Gradient or color start value. */
  from: string;
  /** Gradient or color end value. */
  to: string;
  /** Accent color value. */
  accent: string;
}

/**
 * Content model for the hero section.
 */
export interface HeroContent {
  /** Small introductory text. */
  eyebrow: string;
  /** Main hero headline. */
  title: string;
  /** Supporting subtitle text. */
  subtitle: string;
  /** Longer descriptive body copy. */
  body: string;
  /** Available hero actions. */
  actions: HeroAction[];
  /** Label for the accompanying visual. */
  visualLabel: string;
  /** Color tone settings for the visual. */
  visualTone: HeroVisualTone;
}

/**
 * Color tone configuration for author photo elements.
 */
export interface AuthorPhotoTone {
  /** Gradient or color start value. */
  from: string;
  /** Gradient or color end value. */
  to: string;
  /** Accent color value. */
  accent: string;
}

/**
 * Profile information for the site's author.
 */
export interface AuthorProfile {
  /** Author's display name. */
  name: string;
  /** Author's role or title. */
  role: string;
  /** Short biography. */
  bio: string;
  /** Geographic location or base. */
  location: string;
  /** Accessible label for the avatar or portrait. */
  avatarLabel: string;
  /** Color tone settings for the author photo. */
  photoTone: AuthorPhotoTone;
}

/**
 * Color tone configuration for article imagery.
 */
export interface ArticleImageTone {
  /** Gradient or color start value. */
  from: string;
  /** Gradient or color end value. */
  to: string;
  /** Accent color value. */
  accent: string;
}

/**
 * Preview information for a featured article.
 */
export interface ArticlePreview {
  /** Unique article identifier. */
  id: string;
  /** Article title. */
  title: string;
  /** Short excerpt from the article. */
  excerpt: string;
  /** Category or topic label. */
  category: string;
  /** Publication date string. */
  publishedAt: string;
  /** Estimated reading time string. */
  readTime: string;
  /** Link to the article. */
  href: string;
  /** Accessible label for the article image. */
  imageLabel: string;
  /** Color tone settings for the article image. */
  imageTone: ArticleImageTone;
}

/**
 * A topical category used to group articles.
 */
export interface TopicCategory {
  /** Unique category identifier. */
  id: string;
  /** Display name for the category. */
  name: string;
  /** Description of the category. */
  description: string;
  /** Number of articles in the category. */
  articleCount: number;
}

/**
 * Supported contact channels.
 */
export interface ContactChannel {
  /** Display label for the contact link. */
  label: string;
  /** Destination URL or mailto link. */
  href: string;
  /** Type of contact channel. */
  kind: 'email' | 'github' | 'x' | 'linkedin' | 'rss';
}

/**
 * A link displayed in the site footer.
 */
export interface FooterLink {
  /** Visible link label. */
  label: string;
  /** Destination URL or path. */
  href: string;
}

/**
 * Aggregate content model for the site.
 */
export interface SiteContent {
  /** Site metadata. */
  meta: SiteMeta;
  /** Hero section content. */
  hero: HeroContent;
  /** Author profile content. */
  author: AuthorProfile;
  /** Featured article previews. */
  featuredArticles: ArticlePreview[];
  /** Available topical categories. */
  categories: TopicCategory[];
  /** Site contact channels. */
  contacts: ContactChannel[];
  /** Footer navigation links. */
  footerLinks: FooterLink[];
  /** Footer note or copyright text. */
  footerNote: string;
}

const STYLE_ELEMENT_ID: string = 'apple-ui-global-styles';

/**
 * Semantic class names for the Apple-style UI system.
 */
export const appleUiClasses = Object.freeze({
  page: 'apple-ui-page',
  shell: 'apple-ui-shell',
  section: 'apple-ui-section',
  sectionHeading: 'apple-ui-section-heading',
  grid: 'apple-ui-grid',
  card: 'apple-ui-card',
  pill: 'apple-ui-pill',
  buttonPrimary: 'apple-ui-button-primary',
  buttonSecondary: 'apple-ui-button-secondary',
  mutedText: 'apple-ui-muted-text',
  divider: 'apple-ui-divider',
} as const) as Readonly<{
  readonly page: string;
  readonly shell: string;
  readonly section: string;
  readonly sectionHeading: string;
  readonly grid: string;
  readonly card: string;
  readonly pill: string;
  readonly buttonPrimary: string;
  readonly buttonSecondary: string;
  readonly mutedText: string;
  readonly divider: string;
}>;

function buildStyles(): string {
  return `
:root {
  color-scheme: light;
  --apple-bg: #f5f5f7;
  --apple-surface: rgba(255, 255, 255, 0.78);
  --apple-surface-solid: #ffffff;
  --apple-border: rgba(60, 60, 67, 0.12);
  --apple-text: #1d1d1f;
  --apple-muted: #6e6e73;
  --apple-accent: #0071e3;
  --apple-accent-hover: #0068d1;
  --apple-shadow: 0 12px 40px rgba(0, 0, 0, 0.08);
  --apple-shadow-soft: 0 6px 20px rgba(0, 0, 0, 0.06);
  --apple-radius-card: 24px;
  --apple-radius-pill: 999px;
  --apple-space-1: 0.25rem;
  --apple-space-2: 0.5rem;
  --apple-space-3: 0.75rem;
  --apple-space-4: 1rem;
  --apple-space-5: 1.5rem;
  --apple-space-6: 2rem;
  --apple-space-7: 3rem;
  --apple-space-8: 4rem;
  --apple-max-width: 1120px;
}

html {
  font-family: -apple-system, BlinkMacSystemFont, 'SF Pro Text', 'SF Pro Display', 'Segoe UI', Roboto, Helvetica, Arial, sans-serif;
  line-height: 1.5;
  text-rendering: optimizeLegibility;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
}

body {
  margin: 0;
  color: var(--apple-text);
  background: linear-gradient(180deg, #fbfbfd 0%, var(--apple-bg) 100%);
}

.${appleUiClasses.page} {
  min-height: 100vh;
  background: inherit;
  color: inherit;
}

.${appleUiClasses.shell} {
  max-width: var(--apple-max-width);
  margin: 0 auto;
  padding: var(--apple-space-6) var(--apple-space-5);
}

.${appleUiClasses.section} {
  margin-bottom: var(--apple-space-8);
}

.${appleUiClasses.sectionHeading} {
  margin: 0 0 var(--apple-space-4);
  font-size: clamp(1.5rem, 1.2rem + 1vw, 2.25rem);
  line-height: 1.1;
  letter-spacing: -0.02em;
}

.${appleUiClasses.grid} {
  display: grid;
  gap: var(--apple-space-4);
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
}

.${appleUiClasses.card} {
  background: var(--apple-surface);
  border: 1px solid var(--apple-border);
  border-radius: var(--apple-radius-card);
  box-shadow: var(--apple-shadow-soft);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  padding: var(--apple-space-5);
  transition: transform 180ms ease, box-shadow 180ms ease, border-color 180ms ease;
}

.${appleUiClasses.card}:hover {
  transform: translateY(-2px);
  box-shadow: var(--apple-shadow);
  border-color: rgba(60, 60, 67, 0.18);
}

.${appleUiClasses.pill} {
  display: inline-flex;
  align-items: center;
  gap: var(--apple-space-2);
  padding: var(--apple-space-2) var(--apple-space-3);
  border-radius: var(--apple-radius-pill);
  background: rgba(0, 113, 227, 0.1);
  color: var(--apple-accent);
  font-size: 0.875rem;
  font-weight: 600;
}

.${appleUiClasses.buttonPrimary},
.${appleUiClasses.buttonSecondary} {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 44px;
  padding: 0.75rem 1.1rem;
  border-radius: var(--apple-radius-pill);
  font: inherit;
  font-weight: 600;
  text-decoration: none;
  cursor: pointer;
  transition: transform 180ms ease, background-color 180ms ease, border-color 180ms ease, color 180ms ease, opacity 180ms ease;
}

.${appleUiClasses.buttonPrimary} {
  background: var(--apple-accent);
  color: #ffffff;
  border: 1px solid transparent;
}

.${appleUiClasses.buttonPrimary}:hover {
  background: var(--apple-accent-hover);
}

.${appleUiClasses.buttonSecondary} {
  background: rgba(255, 255, 255, 0.7);
  color: var(--apple-text);
  border: 1px solid var(--apple-border);
}

.${appleUiClasses.buttonSecondary}:hover {
  background: rgba(255, 255, 255, 0.9);
}

.${appleUiClasses.mutedText} {
  color: var(--apple-muted);
}

.${appleUiClasses.divider} {
  width: 100%;
  height: 1px;
  background: var(--apple-border);
  border: 0;
  margin: var(--apple-space-5) 0;
}

@media (max-width: 768px) {
  .${appleUiClasses.shell} {
    padding: var(--apple-space-5) var(--apple-space-4);
  }

  .${appleUiClasses.grid} {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 480px) {
  .${appleUiClasses.shell} {
    padding: var(--apple-space-4) var(--apple-space-3);
  }

  .${appleUiClasses.card} {
    border-radius: 20px;
    padding: var(--apple-space-4);
  }
}

@media (prefers-reduced-motion: reduce) {
  *, *::before, *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
    scroll-behavior: auto !important;
  }
}
`;
}

/**
 * Injects the global Apple-style stylesheet into the document once.
 */
export function injectGlobalStyles(): void {
  if (typeof document === 'undefined') {
    return;
  }

  if (document.getElementById(STYLE_ELEMENT_ID) !== null) {
    return;
  }

  const styleElement: HTMLStyleElement = document.createElement('style');
  styleElement.id = STYLE_ELEMENT_ID;
  styleElement.type = 'text/css';
  styleElement.textContent = buildStyles();
  document.head.appendChild(styleElement);
}

