import type { HeroAction, HeroContent } from './types';
import { appleUiClasses } from './globalStyles';

/**
 * Props for the HeroSection component.
 */
export interface HeroSectionProps {
  /** Content displayed by the hero section. */
  hero: HeroContent;
}

/**
 * Renders a static, responsive Apple-inspired hero section.
 */
export function HeroSection(props: { hero: HeroContent }): React.JSX.Element {
  const { hero } = props;
  const actions: readonly HeroAction[] = Array.isArray(hero.actions) ? hero.actions.slice(0, 2) : [];

  const visualFrameStyle: CSSProperties = {
    ...visualCardBaseStyle,
    background: `linear-gradient(135deg, ${hero.visualTone.from} 0%, ${hero.visualTone.to} 100%)`,
  };

  const accentOrbStyle: CSSProperties = {
    ...orbBaseStyle,
    top: '8%',
    right: '-8%',
    width: '13rem',
    height: '13rem',
    background: `radial-gradient(circle at center, ${hero.visualTone.accent} 0%, transparent 72%)`,
  };

  const secondaryOrbStyle: CSSProperties = {
    ...orbBaseStyle,
    bottom: '-10%',
    left: '-6%',
    width: '12rem',
    height: '12rem',
    background: `radial-gradient(circle at center, ${hero.visualTone.from} 0%, transparent 70%)`,
  };

  const tertiaryOrbStyle: CSSProperties = {
    ...orbBaseStyle,
    top: '36%',
    left: '38%',
    width: '9rem',
    height: '9rem',
    background: `radial-gradient(circle at center, ${hero.visualTone.to} 0%, transparent 70%)`,
  };

  return React.createElement(
    'section',
    {
      className: appleUiClasses.section,
      'aria-labelledby': 'hero-title',
      style: sectionStyle,
    },
    React.createElement(
      'div',
      { style: contentGridStyle },
      React.createElement(
        'div',
        { style: copyColumnStyle },
        React.createElement(
          'div',
          { className: appleUiClasses.pill, style: eyebrowStyle },
          hero.eyebrow,
        ),
        React.createElement('h1', { id: 'hero-title', style: titleStyle }, hero.title),
        React.createElement('p', { style: subtitleStyle }, hero.subtitle),
        React.createElement(
          'p',
          { className: appleUiClasses.mutedText, style: bodyStyle },
          hero.body,
        ),
        React.createElement(
          'div',
          { style: actionsRowStyle },
          ...actions.map((action: HeroAction) =>
            React.createElement(
              'a',
              {
                key: `${action.label}-${action.href}`,
                href: action.href,
                className:
                  action.variant === 'primary'
                    ? appleUiClasses.buttonPrimary
                    : appleUiClasses.buttonSecondary,
                style: actionLinkStyle,
              },
              action.label,
            ),
          ),
        ),
      ),
      React.createElement(
        'div',
        { style: visualColumnStyle },
        React.createElement(
          'div',
          {
            role: 'img',
            'aria-label': hero.visualLabel,
            className: appleUiClasses.card,
            style: visualFrameStyle,
          },
          React.createElement('div', { style: accentOrbStyle }),
          React.createElement('div', { style: secondaryOrbStyle }),
          React.createElement('div', { style: tertiaryOrbStyle }),
