              React.createElement('span', { style: signalDotStyle('rgba(255, 255, 255, 0.78)') }),
              React.createElement('span', { style: signalDotStyle('rgba(255, 255, 255, 0.48)') }),
            ),
            React.createElement('div', { style: visualLabelStyle }, hero.visualLabel),
            React.createElement(
