  padding: 'clamp(3rem, 6vw, 5rem) 0',
};

const contentGridStyle: CSSProperties = {
  display: 'grid',
  gridTemplateColumns: 'repeat(auto-fit, minmax(280px, 1fr))',
  gap: 'clamp(2rem, 4vw, 4rem)',
