  color: 'var(--apple-text)',
  maxWidth: '34rem',
};

const bodyStyle: CSSProperties = {
  margin: 0,
  fontSize: '1rem',
  lineHeight: 1.7,
  maxWidth: '36rem',
};

const actionsRowStyle: CSSProperties = {
  display: 'flex',
  flexWrap: 'wrap',
  gap: '0.875rem',
  paddingTop: '0.5rem',
};

const actionLinkStyle: CSSProperties = {
  textDecoration: 'none',
};

const visualColumnStyle: CSSProperties = {
  display: 'flex',
  justifyContent: 'center',
  minWidth: 0,
};

const visualCardBaseStyle: CSSProperties = {
  position: 'relative',
  overflow: 'hidden',
  width: '100%',
  maxWidth: '34rem',
  minHeight: '30rem',
  borderRadius: '32px',
  boxShadow: '0 24px 80px rgba(0, 0, 0, 0.16)',
  padding: '1.5rem',
  display: 'flex',
  alignItems: 'flex-end',
  justifyContent: 'stretch',
  isolation: 'isolated',
};

const orbBaseStyle: CSSProperties = {
  position: 'absolute',
  borderRadius: '999px',
  filter: 'blur(8px)',
  opacity: 0.9,
  pointerEvents: 'none',
};

const glassPanelStyle: CSSProperties = {
  position: 'relative',
  zIndex: 1,
  width: '100%',
