/**
 * Renders a single featured article card with a gradient image placeholder,
 * article metadata, and a linked title.
 */
export function ArticleCard(props: { article: ArticlePreview }): React.JSX.Element {
  const { article } = props;
  const category: string = article.category.trim().length > 0 ? article.category : 'General';
  const title: string = article.title.trim().length > 0 ? article.title : 'Untitled article';
  const excerpt: string = article.excerpt.trim().length > 0 ? article.excerpt : 'No excerpt available.';
  const publishedAt: string = article.publishedAt.trim().length > 0 ? article.publishedAt : 'Date unavailable';
  const readTime: string = article.readTime.trim().length > 0 ? article.readTime : 'Read time unavailable';
  const href: string = article.href.trim().length > 0 ? article.href : '#';
  const imageLabel: string = article.imageLabel.trim().length > 0 ? article.imageLabel : title;
  const glyphLabel: string = buildGlyphLabel(category, title);

  const mediaStyle: CSSProperties = {
    ...cardMediaStyle,
    background: `linear-gradient(135deg, ${article.imageTone.from} 0%, ${article.imageTone.to} 100%)`,
  };

  const mediaAccentStyle: CSSProperties = {
    ...cardMediaAccentStyle,
    background: `radial-gradient(circle at center, ${article.imageTone.accent} 0%, transparent 72%)`,
  };

  return React.createElement(
    'a',
    {
      href,
      style: cardLinkStyle,
      'aria-label': `${title} — ${category}`,
    },
    React.createElement(
      'article',
      {
        className: appleUiClasses.card,
        style: cardStyle,
      },
      React.createElement(
        'div',
        {
          role: 'img',
          'aria-label': imageLabel,
          style: mediaStyle,
        },
        React.createElement('div', { style: mediaAccentStyle }),
        React.createElement('p', { style: mediaLabelStyle }, imageLabel),
        React.createElement('span', { 'aria-hidden': 'true', style: mediaGlyphStyle }, glyphLabel),
      ),
      React.createElement(
        'div',
        { style: cardBodyStyle },
        React.createElement(
          'span',
          {
            className: appleUiClasses.pill,
            style: categoryStyle,
          },
          category,
        ),
        React.createElement('h3', { style: titleStyle }, title),
        React.createElement(
          'p',
          {
            className: appleUiClasses.mutedText,
            style: excerptStyle,
          },
          excerpt,
        ),
        React.createElement(
          'div',
          {
            className: appleUiClasses.mutedText,
            style: metaStyle,
          },
          React.createElement('time', { dateTime: normalizeDateTime(article.publishedAt) }, publishedAt),
          React.createElement('span', { className: appleUiClasses.divider, 'aria-hidden': 'true' }, '•'),
          React.createElement('span', null, readTime),
        ),
      ),
    ),
  );
}

