 */
export function FeaturedArticlesSection(props: { articles: ArticlePreview[] }): React.JSX.Element {
  const articles: ArticlePreview[] = Array.isArray(props.articles) ? props.articles : [];

  return React.createElement(
    'section',
    {
      className: appleUiClasses.section,
      'aria-labelledby': 'featured-articles-heading',
    },
    React.createElement(
      'div',
      { className: appleUiClasses.shell },
      React.createElement('h2', { id: 'featured-articles-heading', className: appleUiClasses.sectionHeading }, 'Featured Articles'),
      React.createElement(
        'div',
        {
          className: appleUiClasses.grid,
          style: gridStyle,
        },
        articles.length > 0
          ? articles.map((article: ArticlePreview) =>
              React.createElement(ArticleCard, {
                key: article.id,
                article,
              }),
            )
          : React.createElement(
              'p',
              {
                className: appleUiClasses.mutedText,
                style: emptyStateStyle,
              },
              'No featured articles available.',
            ),
      ),
    ),
  );
}

function buildGlyphLabel(category: string, title: string): string {
  const source: string = `${category} ${title}`.trim();
  const characters: string[] = source.match(/[A-Za-z0-9]/g) ?? [];

  if (characters.length === 0) {
    return 'AR';
  }

  return characters.slice(0, 2).join('').toUpperCase();
}

function normalizeDateTime(value: string): string | undefined {
  const trimmedValue: string = value.trim();

  if (trimmedValue.length === 0) {
    return undefined;
  }

  const parsedDate: number = Date.parse(trimmedValue);
  return Number.isNaN(parsedDate) ? undefined : new Date(parsedDate).toISOString();
}

