export function TopicPill(props: { category: TopicCategory }): React.JSX.Element {
  const { category } = props;
  const articleCount: number = Number.isFinite(category.articleCount)
    ? Math.max(0, category.articleCount)
    : 0;
  const articleLabel: string = `${articleCount} ${articleCount === 1 ? 'article' : 'articles'}`;
  const description: string = category.description.trim().length > 0 ? category.description : 'No description available.';

  return (
    React.createElement(
      'article',
      {
        className: `${appleUiClasses.card} ${appleUiClasses.pill}`,
        'aria-label': `${category.name} (${articleLabel})`,
        style: {
          display: 'flex',
          flexDirection: 'column',
          gap: '0.5rem',
          height: '100%',
        },
      },
      React.createElement(
        'div',
        {
          style: {
            display: 'flex',
            alignItems: 'baseline',
            justifyContent: 'space-between',
            gap: '0.75rem',
            flexWrap: 'wrap',
          },
        },
        React.createElement('h3', { style: { margin: 0, fontSize: '1rem', lineHeight: 1.3 } }, category.name),
        React.createElement(
          'span',
          { className: appleUiClasses.mutedText, style: { whiteSpace: 'nowrap', fontSize: '0.875rem' } },
          articleLabel,
        ),
      ),
      React.createElement('p', { className: appleUiClasses.mutedText, style: { margin: 0, fontSize: '0.95rem' } }, description),
    )
  );
}

