/**
 * Props for the footer section.
 */
export interface FooterSectionProps {
  /** Footer navigation links. */
  footerLinks: FooterLink[];
  /** Supporting note text shown below the divider. */
  footerNote: string;
}

/**
 * Returns whether a footer link is valid for rendering.
 */
function isValidFooterLink(link: FooterLink | null | undefined): link is FooterLink {
  return Boolean(link && link.label.trim() && link.href.trim());
}

/**
 * Builds the footer navigation link list when valid links exist.
 */
function buildLinkList(footerLinks: FooterLink[]): JSX.Element | null {
  const validLinks: FooterLink[] = footerLinks.filter(isValidFooterLink);

  if (validLinks.length === 0) {
    return null;
  }

  const listStyle: CSSProperties = {
    listStyle: 'none',
    margin: 0,
    padding: 0,
    display: 'flex',
    flexWrap: 'wrap',
    gap: '0.75rem 1.25rem',
    alignItems: 'center',
    justifyContent: 'center',
  };

  const linkStyle: CSSProperties = {
    color: 'inherit',
    textDecoration: 'none',
    fontSize: '0.875rem',
    fontWeight: 400,
    letterSpacing: '-0.01em',
  };

  return createElement(
    'nav',
    { 'aria-label': 'Footer', className: appleUiClasses.mutedText },
    createElement(
      'ul',
      { style: listStyle },
      validLinks.map((link: FooterLink) =>
        createElement(
          'li',
          { key: `${link.label}-${link.href}` },
          createElement('a', { href: link.href, style: linkStyle }, link.label),
        ),
      ),
    ),
  );
}

/**
 * Renders a minimal Apple-style footer with navigation links and a note.
 */
export function FooterSection(props: { footerLinks: FooterLink[]; footerNote: string }): JSX.Element {
  const footerNoteText: string = props.footerNote.trim();

  const containerStyle: CSSProperties = {
    paddingTop: '1.5rem',
    paddingBottom: '1.5rem',
    display: 'flex',
    flexDirection: 'column',
    gap: '1rem',
  };

  const dividerStyle: CSSProperties = {
    margin: 0,
  };

  const noteStyle: CSSProperties = {
    margin: 0,
    fontSize: '0.8125rem',
    lineHeight: 1.5,
    textAlign: 'center',
  };

  return createElement(
    'footer',
    { className: appleUiClasses.section, style: containerStyle },
    buildLinkList(props.footerLinks),
    createElement('div', { className: appleUiClasses.divider, 'aria-hidden': 'true', style: dividerStyle }),
    createElement('p', { className: appleUiClasses.mutedText, style: noteStyle }, footerNoteText),
  );
}

