import * as React from 'react';
import type { CSSProperties } from 'react';

import { AboutSection } from './AboutSection';
import { FeaturedArticlesSection } from './FeaturedArticlesSection';
import { FooterSection } from './FooterSection';
import { HeroSection } from './HeroSection';
import { TopicsSection } from './TopicsSection';
import { siteContent } from './siteContent';

const appStyle: CSSProperties = {
  display: 'flex',
  flexDirection: 'column',
  width: '100%',
  minHeight: '100vh',
};

/**
 * Renders the single-page application layout for the site.
 *
 * @returns The composed page element.
 */
export default function App(): React.JSX.Element {
  React.useEffect((): void => {
    if (typeof document === 'undefined') {
      return;
    }

    const title: string = siteContent.meta.title.trim();
    const description: string = siteContent.meta.description.trim();

    if (title.length > 0) {
      document.title = title;
    }

    if (description.length === 0) {
      return;
    }

    const selector: string = 'meta[name="description"]';
    let metaTag: HTMLMetaElement | null = document.head.querySelector(selector);

    if (metaTag === null) {
      metaTag = document.createElement('meta');
      metaTag.setAttribute('name', 'description');
      document.head.appendChild(metaTag);
    }

    metaTag.setAttribute('content', description);
  }, []);

  return React.createElement(
    'main',
    { style: appStyle },
    React.createElement(HeroSection, { hero: siteContent.hero }),
    React.createElement(AboutSection, {
      profile: siteContent.author,
      contacts: siteContent.contacts,
    }),
    React.createElement(FeaturedArticlesSection, {
      articles: siteContent.featuredArticles,
    }),
    React.createElement(TopicsSection, {
      categories: siteContent.categories,
    }),
    React.createElement(FooterSection, {
      footerLinks: siteContent.footerLinks,
      footerNote: siteContent.footerNote,
    }),
  );
}

import * as React from 'react';
import { createRoot, type Root } from 'react-dom/client';

import App from './App';
import { injectGlobalStyles } from './globalStyles';

let hasInjectedGlobalStyles: boolean = false;
let rootInstance: Root | null = null;

/**
 * Boots the application into the provided container.
 *
 * @param container - The root DOM element to mount into.
 */
export function bootstrapApp(container: HTMLElement | null): void {
  if (container === null) {
    return;
  }

  if (!hasInjectedGlobalStyles) {
    injectGlobalStyles();
    hasInjectedGlobalStyles = true;
  }

  if (rootInstance === null) {
    rootInstance = createRoot(container);
  }

  rootInstance.render(React.createElement(App));
}

bootstrapApp(document.getElementById('root'));

import * as React from 'react';
import { render, screen } from '@testing-library/react';
import { describe, expect, it } from 'vitest';

import App from './App';
import { siteContent } from './siteContent';

/**
 * Returns the first featured article title from site content.
 *
 * @returns A non-empty featured article title.
 * @throws If no featured article title is available.
 */
function getFirstFeaturedArticleTitle(): string {
  const firstFeaturedArticleTitle: string | undefined = siteContent.featuredArticles[0]?.title;

  if (typeof firstFeaturedArticleTitle !== 'string' || firstFeaturedArticleTitle.trim().length === 0) {
    throw new Error('Expected at least one featured article title in siteContent.featuredArticles.');
  }

  return firstFeaturedArticleTitle;
}

/**
 * Returns the first category name from site content.
 *
 * @returns A non-empty category name.
 * @throws If no category name is available.
 */
function getFirstCategoryName(): string {
  const firstCategoryName: string | undefined = siteContent.categories[0]?.name;

  if (typeof firstCategoryName !== 'string' || firstCategoryName.trim().length === 0) {
    throw new Error('Expected at least one category name in siteContent.categories.');
  }

  return firstCategoryName;
}

/**
 * Returns the first footer link label from site content.
 *
 * @returns A non-empty footer link label.
 * @throws If no footer link label is available.
 */
function getFirstFooterLinkLabel(): string {
  const firstFooterLinkLabel: string | undefined = siteContent.footerLinks[0]?.label;

  if (typeof firstFooterLinkLabel !== 'string' || firstFooterLinkLabel.trim().length === 0) {
    throw new Error('Expected at least one footer link in siteContent.footerLinks.');
  }

  return firstFooterLinkLabel;
}

describe('App smoke test', (): void => {
  it('renders key content from siteContent', (): void => {
    render(React.createElement(App));

    expect(screen.getByText(siteContent.hero.title)).toBeTruthy();
    expect(screen.getByText(siteContent.author.name)).toBeTruthy();
    expect(screen.getByText(getFirstFeaturedArticleTitle())).toBeTruthy();
    expect(screen.getAllByText(getFirstCategoryName()).length).toBeGreaterThan(0);
    expect(screen.getByRole('link', { name: getFirstFooterLinkLabel() })).toBeTruthy();
  });
});
